      "법규명령과 행정규칙의 구별 — 법규명령은 국민과 법원을 구속하는 대외적 구속력(법규성)을 갖지만, 행정규칙은 원칙적으로 행정조직 내부에서만 효력을 갖고 대외적 구속력이 없습니다.",
