    "titleKo": "법규명령",
    "definition": "**위임명령**은 법률이 **구체적으로 범위를 정하여 위임**해야 적법하다(포괄위임금지). 위임받은 사항을 전혀 정하지 않고 그대로 다시 넘기는 **복위임은 금지**된다.",
    "intuition": "위임의 근거가 사후에 부여되면 그때부터 유효할 뿐 소급하지 않는다.",
    "keyPoints": [
      "위임입법의 한계 — 헌법 제75조가 요구하는 위임의 구체성·명확성을 갖추어야 하며, 다양한 사실관계를 규율하거나 수시로 변화하는 분야는 위임의 명확성이 완화됩니다. 처벌법규의 위임은 죄형법정주의상 형벌의 종류·상한·폭을 법률로 명확히 규정한 경우에만 예외적으로 허용되고, 조세법률주의상 과세요건을 하위법령에 백지위임할 수 없습니다.",
      "재위임의 허용범위 — 위임받은 사항의 대강을 정하고 그중 특정사항의 범위를 정하여 하위법령에 다시 위임하는 재위임은 허용됩니다. 이 법리는 조례가 법률로부터 위임받은 사항을 다시 규칙·고시 등에 재위임하는 경우에도 마찬가지로 적용됩니다.",
      "위임근거의 사후 소멸·부여 — 법규명령이 위임의 근거 없이 제정되어 무효였더라도, 사후 법 개정으로 위임의 근거가 부여되면 그때부터 유효한 법규명령이 됩니다(소급 치유 아님, 장래효). 반대로 유효하게 성립한 법규명령이라도 위임의 근거가 된 법률에 위헌결정이 선고되면 그 법규명령은 원칙적으로 효력을 상실합니다.",
      "법규명령의 처분성과 사법통제 — 법규명령이 별도의 집행행위 없이 직접 국민의 구체적 권리의무에 영향을 미치는 경우(처분적 법규명령)에는 항고소송·헌법소원의 대상이 됩니다. 대법원규칙(예: 법무사법 시행규칙)도 직접 기본권을 침해하면 헌법소원의 대상이 됩니다(헌재). 행정입법부작위는 부작위위법확인소송의 대상이 되지 않고, 헌법소원의 방법으로만 다툴 수 있습니다.",
      "법규명령 형식의 제재적 처분기준 — 대통령령(시행령) 형식의 제재적 처분기준은 그 자체로 법규명령의 효력을 갖지만, 부령(시행규칙) 형식의 제재적 처분기준은 형식은 부령이라도 그 실질은 행정청 내부의 사무처리준칙(행정규칙)에 불과하여 대외적 구속력이 없다는 것이 판례의 확립된 입장입니다('행정규칙' 단원과 연계)."
    ],
