    "keyPoints": [
      "공정력과 구성요건적 효력의 구별 — 공정력은 상대방·이해관계인에 대한 효력으로 법적 안정성에 근거를 두고, 구성요건적 효력은 다른 국가기관(민·형사법원 등)에 대한 효력으로 국가기관 상호간 권한 존중(권력분립)에 근거를 둡니다. 이론적 근거가 다르다는 점에서 양자를 동일시하는 서술은 틀린 함정입니다.",
      "선결문제와 공정력의 관계 — 행정처분의 위법성이 선결문제인 경우(취소사유에 불과한 처분의 위법을 이유로 한 국가배상청구 등)에는 처분을 취소하지 않고도 민사법원이 스스로 위법 여부를 판단할 수 있습니다. 반면 행정처분의 효력 유무 자체가 선결문제인 경우(취소사유에 불과한 과세처분에 따라 납부한 세금의 부당이득반환청구 등)에는 그 처분이 취소되지 않는 한 효력을 부인할 수 없습니다. 처분이 당연무효인 경우에는 항상 선결문제로 스스로 판단할 수 있습니다.",
      "공정력과 무면허·무허가 판단 — 연령미달 결격자가 취득한 운전면허는 취소되지 않는 한 유효하므로 그 운전은 무면허운전이 아닙니다. 영업허가취소처분이 행정쟁송에서 취소되면 그 취소처분은 처음부터 효력이 없었던 것이 되어, 취소처분 이후의 영업행위도 무허가영업이 아니게 됩니다.",
      "불가쟁력·불가변력과 국가배상의 관계 — 처분에 불가쟁력이 발생하여 더 이상 다툴 수 없게 되었더라도, 그로 인해 손해를 입은 국민이 국가배상을 청구하는 것은 별도로 가능합니다(불가쟁력이 국가배상청구권까지 소멸시키는 것은 아님)."
    ],
