      "실효의 의의 — 적법하게 성립한 행정행위가 행정청의 별도 의사표시 없이 일정한 사유(대상의 소멸, 해제조건의 성취·종기의 도래, 목적의 달성·달성불능) 발생만으로 장래를 향해 당연히 효력을 상실하는 것을 말합니다.",
