      "투명성의 원칙(제5조) — 행정작용은 그 내용이 명확해야 하며, 법령등의 내용이 명확하지 아니한 경우 국민(사업자 등 포함)은 그 해석을 요청할 수 있고 행정청은 특별한 사정이 없으면 그에 따라야 합니다."
