    "titleKo": "행정절차의 내용",
    "definition": "처분절차는 여섯이다 — **신청의 접수·처분기준의 설정과 공표·사전통지·의견청취·이유제시·처분의 방식과 송달**이다.",
    "intuition": "신청에 대한 거부처분은 원칙적으로 사전통지의 대상이 아니라는 점이 최빈출 논점이다.",
    "keyPoints": [
      "거부처분과 사전통지 — 신청에 대한 거부처분은 원칙적으로 당사자에게 의무를 부과하거나 권익을 제한하는 처분이 아니므로 사전통지·의견제출의 대상이 아닙니다. 다만 항만시설 사용허가 거부처럼 실질적으로 기존의 이익을 제한하는 성격이 강한 경우에는 사전통지가 필요할 수 있습니다. 영업자지위승계신고를 수리하는 처분은 종전 영업자의 권익을 제한하는 처분이므로 종전 영업자에게 사전통지를 해야 합니다.",
      "청문의 실시 요건 — 다른 법령등에서 청문을 규정한 경우, 행정청이 필요하다고 인정하는 경우, 인허가 등의 취소·신분자격의 박탈·법인 설립허가의 취소 시 당사자등의 신청이 있는 경우(의견제출기한 내)에 청문을 실시합니다. 청문통지서가 반송되었거나 상대방이 청문일시에 불출석하였다는 이유만으로 청문을 실시하지 않고 한 침해적 처분은 위법합니다.",
      "이유제시의 원칙과 예외 — 신청 내용을 모두 그대로 인정하는 처분, 단순·반복적 처분이나 경미한 처분으로서 당사자가 근거를 명백히 알 수 있는 경우에는 이유제시를 생략할 수 있으나, 처분 후 당사자가 요청하면 그 근거와 이유를 제시해야 합니다. 당사자가 근거를 알 수 있을 정도로 이유를 제시했다면 구체적으로 명시하지 않았어도 위법하지 않습니다.",
      "공무원 인사관계 처분과 절차 — 직위해제처분에는 「행정절차법」상 사전통지·의견청취 규정이 적용됩니다. 반면 진급예정자명단에 포함된 자에 대해 의견제출 기회 없이 진급선발을 취소한 처분은 절차상 하자로 위법합니다('행정절차의 적용범위'의 적용제외는 성질상 불가피한 경우에 한하는 제한적 해석에 따름).",
      "송달과 효력발생(도달주의) — 처분의 통지는 상대방이 인식할 수 있는 상태에 둠으로써 족하며 객관적으로 행정처분으로 인식할 수 있도록 고지하면 됩니다. 보통우편으로 발송한 경우 도달을 추정할 수 없고, 등기우편이라도 수취인이 그 주소에 실제 거주하지 않으면 도달사실을 처분청이 입증해야 합니다. 송달이 불가능한 경우 관보·공보·게시판·일간신문 중 하나 이상 및 인터넷에 공고해야 하며, 다른 법령에 특별한 규정이 없는 한 공고일부터 14일이 지난 때에 효력이 발생합니다."
    ],
